const raw = $input.first().json;
const body = (raw && typeof raw.body === 'object' && raw.body !== null) ? raw.body : raw;

const queryId = body.queryId ?? null;
const ticketId = body.ticketId ?? null;
const title = String(body.title ?? '').trim();
const description = String(body.description ?? '').trim();
const question = String(body.question ?? '').trim();
const category = String(body.category ?? 'OTROS').trim();
const priority = String(body.priority ?? 'MEDIA').trim();

const hasText = question.length > 0 || description.length > 0;
const isValid = hasText && queryId !== null;

const queryText = [
  title ? `Título: ${title}` : '',
  description ? `Descripción: ${description}` : '',
  question ? `Consulta: ${question}` : '',
  category ? `Categoría reportada: ${category}` : ''
].filter(Boolean).join('\n');

const envBase = ($env.BACKEND_BASE_URL || '').trim();
const resolvedCallbackUrl = envBase
  ? `${envBase.replace(/\/$/, '')}/api/v1/integrations/n8n/callback`
  : (body.callbackUrl || 'http://backend:8051/api/v1/integrations/n8n/callback');

const scoreThreshold = Number($env.QDRANT_SCORE_THRESHOLD || 0.70);

return [{
  json: {
    isValid: String(isValid),
    queryId,
    ticketId,
    title,
    description,
    question,
    category,
    priority,
    queryText,
    resolvedCallbackUrl,
    scoreThreshold: Number.isFinite(scoreThreshold) ? scoreThreshold : 0.70
  }
}];

const inputData = $('Normalize & Validate Input').first().json;
const threshold = Number(inputData.scoreThreshold ?? 0.70);
const rawResults = Array.isArray($input.first().json?.result)
  ? $input.first().json.result
  : [];

const filtered = rawResults
  .filter(r =>
    typeof r.score === 'number' &&
    r.score >= threshold &&
    r.payload &&
    r.payload.active !== false &&
    r.payload.verified !== false
  )
  .slice(0, 5);

if (filtered.length === 0) {
  return [{
    json: {
      hasSources: 'false',
      threshold,
      sources: [],
      contextText: '',
      confidenceScore: 0.0
    }
  }];
}

const contextBlocks = filtered.map((r, idx) => {
  const p = r.payload || {};
  const articleId = Number(p.articleId ?? r.id);
  const score = Number(r.score).toFixed(4);
  return [
    `--- FUENTE #${idx + 1} (articleId: ${articleId}, similitud: ${score}) ---`,
    `Título: ${p.title || 'Sin título'}`,
    `Categoría: ${p.category || 'OTROS'}`,
    `Problema: ${p.problem || ''}`,
    p.symptoms ? `Síntomas: ${p.symptoms}` : '',
    p.cause ? `Causa raíz: ${p.cause}` : '',
    `Solución documentada: ${p.solution || ''}`
  ].filter(Boolean).join('\n');
});

const sources = filtered.map(r => ({
  articleId: Number(r.payload?.articleId ?? r.id),
  similarityScore: Math.round(Number(r.score) * 10000) / 10000
}));

const confidenceScore = sources[0]?.similarityScore ?? 0.0;

return [{
  json: {
    hasSources: 'true',
    threshold,
    sources,
    contextText: contextBlocks.join('\n\n'),
    confidenceScore
  }
}];

const inputData = $('Normalize & Validate Input').first().json;
const retrieval = $('Evaluate Retrieval & Build Context').first().json;
const llmResponse = $input.first().json;

const rawContent = String(llmResponse?.choices?.[0]?.message?.content || '').trim();
const cleaned = rawContent
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

let parsed = {};
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    responseText: rawContent || 'Orientación generada a partir de las fuentes recuperadas.',
    suggestedSteps: 'Revisar los procedimientos indicados en las fuentes adjuntas.',
    suggestedPriority: null
  };
}

const validPriorities = new Set(['BAJA', 'MEDIA', 'ALTA', 'CRITICA']);
const candidatePriority = String(parsed.suggestedPriority || '').toUpperCase().trim();
const suggestedPriority = validPriorities.has(candidatePriority) ? candidatePriority : null;

const responseText = String(parsed.responseText || '').trim()
  || 'Se encontraron artículos relevantes en la base de conocimiento; revisar las fuentes adjuntas.';
const suggestedSteps = String(parsed.suggestedSteps || '').trim()
  || 'Aplicar los pasos documentados en los artículos fuente.';

return [{
  json: {
    callbackUrl: inputData.resolvedCallbackUrl,
    payload: {
      queryId: inputData.queryId,
      ticketId: inputData.ticketId,
      status: 'RESPONDIDA',
      responseText,
      suggestedSteps,
      modelUsed: llmResponse?.model || ($env.OPENROUTER_CHAT_MODEL || 'openai/gpt-4o-mini'),
      confidenceScore: retrieval.confidenceScore,
      suggestedPriority,
      sources: retrieval.sources
    }
  }
}];

const inputData = $('Normalize & Validate Input').first().json;
const retrieval = $('Evaluate Retrieval & Build Context').first().json;
const threshold = retrieval?.threshold ?? inputData.scoreThreshold ?? 0.70;

return [{
  json: {
    callbackUrl: inputData.resolvedCallbackUrl,
    payload: {
      queryId: inputData.queryId,
      ticketId: inputData.ticketId,
      status: 'SIN_RESULTADOS',
      responseText: `No se encontraron soluciones verificadas en la base de conocimiento que superen el umbral mínimo de similitud (${threshold}). No se genera solución automática sin respaldo documental.`,
      suggestedSteps: '1. Escalar el incidente al técnico especialista según su categoría. 2. Diagnosticar manualmente el problema. 3. Documentar la solución como un nuevo artículo verificado al cerrar el ticket.',
      modelUsed: 'qdrant-threshold-filter',
      confidenceScore: 0.0,
      sources: []
    }
  }
}];

const inputData = $('Normalize & Validate Input').first().json;
const errItem = $input.first().json || {};
const errorMessage = errItem?.error?.message
  || errItem?.message
  || 'Fallo al comunicarse con el servicio de embeddings, Qdrant o modelo generativo.';

return [{
  json: {
    callbackUrl: inputData.resolvedCallbackUrl,
    payload: {
      queryId: inputData.queryId,
      ticketId: inputData.ticketId,
      status: 'ERROR',
      responseText: `Error durante la orquestación inteligente en n8n: ${errorMessage}`,
      suggestedSteps: '1. Verificar conectividad y credenciales de OpenRouter y Qdrant. 2. Reintentar el análisis inteligente o atender manualmente.',
      modelUsed: 'n8n-error-handler',
      confidenceScore: 0.0,
      sources: []
    }
  }
}];
